SELECT ps.sku_sn AS sn, p.product_id AS productId, ps.sku_id AS skuId, 1 AS matchType, 0 AS skuCount FROM product_sku ps INNER JOIN product p ON p.product_id = ps.product_id LEFT JOIN store_product sp ON sp.product_id = p.product_id AND sp.shop_id = #{shopId} WHERE p.is_delete = 0 AND p.vendor_id IS NULL AND (p.shop_id = #{shopId} OR sp.shop_id = #{shopId}) AND ps.sku_sn IN
#{sn}
UNION ALL
SELECT p.product_sn AS sn, p.product_id AS productId, 0 AS skuId, 2 AS matchType, (SELECT COUNT(*) FROM product_sku s WHERE s.product_id = p.product_id) AS skuCount FROM product p LEFT JOIN store_product sp ON sp.product_id = p.product_id AND sp.shop_id = #{shopId} WHERE p.is_delete = 0 AND p.vendor_id IS NULL AND (p.shop_id = #{shopId} OR sp.shop_id = #{shopId}) AND p.product_sn IN
#{sn}

SELECT DISTINCT p.product_id
FROM product p
    LEFT JOIN store_product sp ON sp.product_id = p.product_id
        AND sp.shop_id = #{shopId}
        AND sp.is_delete = 0
WHERE p.is_delete = 0
    AND p.vendor_id IS NULL
    AND (
        p.shop_id = #{shopId}
        OR (p.shop_id = 0 AND sp.shop_id = #{shopId})
    )
    AND p.product_id IN

        #{productId}
